// Read server-side configuration for a compatible messages API.
const { MODEL_API_URL, MODEL_API_KEY, MODEL_ID } = process.env

if (!MODEL_API_URL || !MODEL_API_KEY || !MODEL_ID) {
  throw new Error('Missing model API configuration')
}

// Send one request with a bounded network wait.
const response = await fetch(MODEL_API_URL, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${MODEL_API_KEY}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model: MODEL_ID,
    messages: [
      { role: 'system', content: 'Plan relaxed trips. Do not invent opening hours.' },
      { role: 'user', content: 'Plan a relaxed two-day trip to Hangzhou with an older family member.' }
    ]
  }),
  signal: AbortSignal.timeout(30_000)
})

if (!response.ok) {
  throw new Error(`Model request failed: ${response.status}`)
}

// Inspect the service response before selecting its generated text.
const result = await response.json()
console.log(result)
